#include "backend.h"
#include "owner_compat.h"
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>
static int checks=0;static void need(bool ok,const char*msg){++checks;if(!ok){fprintf(stderr,"check %d: %s\n",checks,msg);abort();}}
static unsigned get16(const std::vector<uint8_t>&v,size_t p){return v[p]|((unsigned)v[p+1]<<8);}
static std::vector<uint8_t> game(){std::vector<uint8_t>b(arduboy_game_pack(nullptr,0)),again(b.size());need(arduboy_game_pack(b.data(),b.size())==b.size(),"full typed state size");need(arduboy_game_pack(again.data(),again.size())==again.size()&&b==again,"pack is read only including original score one-past cursor");need(b[16]==0&&b[72]==0,"EEPROM and original Playtune boundary no fault");return b;}
static size_t owner_bytes(){ObonoWriter w(nullptr);obono_owner_pack(w);obono_audio_pack(w);return w.size();}
static size_t G(){return 8+owner_bytes()+2+35;}
static void advance(unsigned n){while(n){unsigned x=n>32?32:n;arduboy_pxa_advance(x);n-=x;}}
static void hold(uint8_t b,unsigned n){arduboy_pxa_pointer(b,0);advance(n);arduboy_pxa_pointer(0,1);advance(32);}
static void tap(uint8_t b){hold(b,64);}
int main(){arduboy_pxa_boot(20261010);auto b=game();printf("{\"game_wire_bytes\":%zu,\"owner_bytes\":%zu,",b.size(),owner_bytes());need(b[0]==1&&b[1]==16&&b[2]==0,"typed original bootstrap");need(b[8+owner_bytes()]==120,"original 120 frame logo");need(b.size()==8+owner_bytes()+2+35+19+896,"full inactive BOX128 and SNOW64 state");need(b.size()<=4096,"owned game state capacity");need(arduboy_pxa_state.constructors==1,"cold constructor exactly once");need(arduboy_game_pack(b.data(),b.size()-1)==0,"short pack rejected without truncation");for(auto x:arduboy_pxa_state.eeprom)need(x==255,"fresh FF EEPROM");advance(2200);b=game();need(b[2]==1,"original logo title transition");need(arduboy_pxa_state.fault==0&&arduboy_pxa_state.dropped_steps==0,"original clock no drops");tap(4);advance(2050);b=game();size_t g=G();need(b[2]==2&&b[g]==1,"original game ready after two seconds");need(b[g+14]==64,"original cat moves from160 to64");need(get16(b,g+8)<7200&&get16(b,g+8)>7000,"original two minute timer");tap(16);b=game();need(b[g+16]>0,"ordinary DOWN meow");unsigned guard=0;while(get16(b,g+11)==0&&b[g]==1&&guard++<300){advance(32);b=game();}need(get16(b,g+11)>0&&b[g+17]>=2,"ordinary initial bounce splits gift and scores");unsigned bounced=get16(b,g+11);tap(8);b=game();need(b[g]==3,"original A pause");auto paused=b;advance(500);b=game();need(!memcmp(b.data()+g,paused.data()+g,b.size()-g),"original game fields freeze on pause");tap(4);b=game();need(b[g]==1,"original B resumes");hold(32,2200);b=game();need(b[g+14]==0,"ordinary LEFT reaches exact clamp0");guard=0;while(b[g]!=2&&guard++<500){advance(32);b=game();}need(b[g]==2&&b[g+17]==0,"all original gifts lost natural game over");need(arduboy_pxa_state.eeprom[832]=='O'&&arduboy_pxa_state.eeprom[833]=='B'&&arduboy_pxa_state.eeprom[834]=='N'&&arduboy_pxa_state.eeprom[835]==3,"original record EEPROM signature");need(get16(b,g+11)>=bounced,"score retained at death");tap(4);b=game();need(b[g]==0&&get16(b,g+11)==0,"original B retry resets score and timer");advance(2200);b=game();need(b[g]==1&&b[g+17]>0,"original retry recreates first gift");hold(64,2300);b=game();need(b[g+14]==128,"ordinary RIGHT reaches exact clamp128");need(arduboy_pxa_state.fault==0&&arduboy_pxa_state.dropped_steps==0,"ordinary gameplay no provider fault");uint8_t ee[1024];memcpy(ee,arduboy_pxa_state.eeprom,1024);unsigned clock=arduboy_pxa_state.clock_ms;arduboy_pxa_new();b=game();need(b[2]==0&&b[8+owner_bytes()]==120,"NEW original full logo reset");need(arduboy_pxa_state.clock_ms==clock,"NEW preserves activity clock");need(!memcmp(ee,arduboy_pxa_state.eeprom,1024),"NEW preserves session EEPROM");need(arduboy_pxa_state.constructors==1,"NEW no extra frontend constructor");advance(2200);b=game();need(b[10+owner_bytes()+6]==2,"stored record reloaded after NEW");need(b[16]==0,"owner EEPROM bounds no fault");printf("\"natural_score\":%u,\"passed\":true,\"checks\":%d,\"ordinary_input_only\":true,\"native_boots\":1,\"native_restores\":0}\n",bounced,checks);}
